import pyomo.environ as pyo

GOLD_ANSWER = None

DATA = {
    "machines": [0, 1],
    "products": [0, 1],
    "periods": [0, 1, 2],

    "setup_cost": 149.1695690337089,
    "startup_cost": 69.24269269143792,

    "holding_cost": {
        0: 1.080318154052025,
        1: 1.143069947055348,
    },
    "backlog_cost": {
        0: 6.798895023015501,
        1: 6.372651501311341,
    },

    "demand": {
        (0, 0): 22.92965094851524,
        (0, 1): 19.03396834281949,
        (0, 2): 18.90167422155575,
        (1, 0): 19.80185049682801,
        (1, 1): 24.22810173621122,
        (1, 2): 16.84556169689551,
    },

    "capacity": {
        0: 76.7045484622153,
        1: 69.3695364951939,
    },

    "startup_time": 0.0,

    "initial_inventory": {
        0: 0.0,
        1: 0.0,
    },
    "initial_backlog": {
        0: 0.0,
        1: 0.0,
    },
    "initial_machine_used": {
        0: 0,
        1: 0,
    },

    "big_m_setup": {
        0: 76.7045484622153,
        1: 69.3695364951939,
    },
}


def build_model(data=None):
    d = data or DATA

    M = list(d["machines"])
    P = list(d["products"])
    T = list(d["periods"])

    model = pyo.ConcreteModel()

    model.M = pyo.Set(initialize=M)
    model.P = pyo.Set(initialize=P)
    model.T = pyo.Set(initialize=T)

    model.y = pyo.Var(model.M, model.P, model.T, within=pyo.Binary)
    model.z = pyo.Var(model.M, model.P, model.T, within=pyo.Binary)
    model.x = pyo.Var(model.M, model.P, model.T, within=pyo.NonNegativeReals)
    model.I = pyo.Var(model.P, model.T, within=pyo.NonNegativeReals)
    model.B = pyo.Var(model.P, model.T, within=pyo.NonNegativeReals)
    model.used = pyo.Var(model.M, model.T, within=pyo.Binary)

    model.obj = pyo.Objective(
        expr=(
            d["setup_cost"] * sum(model.y[m, p, t] for m in M for p in P for t in T)
            + d["startup_cost"] * sum(model.z[m, p, t] for m in M for p in P for t in T)
            + sum(d["holding_cost"][p] * model.I[p, t] for p in P for t in T)
            + sum(d["backlog_cost"][p] * model.B[p, t] for p in P for t in T)
        ),
        sense=pyo.minimize,
    )

    def balance_rule(m, p, t):
        if t == T[0]:
            initial_inv = d["initial_inventory"][p]
            initial_back = d["initial_backlog"][p]
        else:
            initial_inv = model.I[p, T[T.index(t) - 1]]
            initial_back = model.B[p, T[T.index(t) - 1]]

        return (
            sum(model.x[m, p, t] for m in M)
            + initial_inv
            - initial_back
            == d["demand"][(p, t)] + model.I[p, t] - model.B[p, t]
        )

    model.balance = pyo.Constraint(model.P, model.T, rule=balance_rule)

    def capacity_rule(m, machine, product, t):
        return (
            model.x[machine, product, t]
            + d["startup_time"] * model.z[machine, product, t]
            <= d["capacity"][machine] * model.y[machine, product, t]
        )

    model.capacity = pyo.Constraint(model.M, model.P, model.T, rule=capacity_rule)

    def one_product_rule(m, machine, t):
        return sum(model.y[machine, product, t] for product in P) <= 1

    model.one_product = pyo.Constraint(model.M, model.T, rule=one_product_rule)

    def used_rule(m, machine, product, t):
        return model.y[machine, product, t] <= model.used[machine, t]

    model.used_rule = pyo.Constraint(model.M, model.P, model.T, rule=used_rule)

    def startup_rule(m, machine, product, t):
        idx = T.index(t)
        if idx == 0:
            prior = d["initial_machine_used"][machine]
        else:
            prior = model.used[machine, T[idx - 1]]
        return model.z[machine, product, t] >= model.y[machine, product, t] - prior

    model.startup = pyo.Constraint(model.M, model.P, model.T, rule=startup_rule)

    def setup_big_m_rule(m, machine, product, t):
        return model.x[machine, product, t] <= d["big_m_setup"][machine] * model.y[machine, product, t]

    model.setup_big_m = pyo.Constraint(model.M, model.P, model.T, rule=setup_big_m_rule)

    return model
